1	import java.awt.Color;
2	import java.util.HashMap;
3	
4	/**
5	 * This class collects and provides some statistical data on the state 
6	 * of a field. It is flexible: it will create and maintain a counter 
7	 * for any class of object that is found within the field.
8	 * 
9	 * @version 2022.03.02
10	 */
11	public class FieldStats
12	{
13	    // A shared weather object between the organisms and the simulator
14	    public static final Weather weather = Weather.getWeather();
15	    // Counters for each type of entity (fox, rabbit, etc.) in the simulation.
16	    private HashMap<Class, Counter> counters;
17	    // Whether the counters are currently up to date.
18	    private boolean countsValid;
19	    // The step of the simulation
20	    private int step;
21	
22	    /**
23	     * Construct a FieldStats object.
24	     */
25	    public FieldStats(int steps)
26	    {
27	        // Set up a collection for counters for each type of animal that
28	        // we might find
29	        step = steps;
30	        counters = new HashMap<>();
31	        countsValid = true;
32	    }
33	
34	    /**
35	     * Get details of what is in the field.
36	     * @return A string describing what is in the field.
37	     */
38	    public String getPopulationDetails(Field field)
39	    {
40	        ++step;
41	        StringBuffer buffer = new StringBuffer();
42	        if(!countsValid) {
43	            generateCounts(field);
44	        }
45	        for(Class key : counters.keySet()) {
46	            Counter info = counters.get(key);
47	            buffer.append(info.getName());
48	            buffer.append(": ");
49	            buffer.append(info.getCount());
50	            buffer.append(' ');
51	        }
52	        buffer.append("Weather: " + weather.getCurrentWeather());
53	        buffer.append(" Time: " + getTimeOfDay());
54	        return buffer.toString();
55	    }
56	    
57	    private String getTimeOfDay()
58	    {
59	        if(step % 80<=55)
60	        {
61	            return "Day";
62	        }
63	        return "Night";
64	    }
65	    
66	    /**
67	     * Invalidate the current set of statistics; reset all 
68	     * counts to zero.
69	     */
70	    public void reset()
71	    {
72	        countsValid = false;
73	        for(Class key : counters.keySet()) {
74	            Counter count = counters.get(key);
75	            count.reset();
76	        }
77	    }
78	
79	    /**
80	     * Increment the count for one class of animal.
81	     * @param animalClass The class of animal to increment.
82	     */
83	    public void incrementCount(Class animalClass)
84	    {
85	        Counter count = counters.get(animalClass);
86	        if(count == null) {
87	            // We do not have a counter for this species yet.
88	            // Create one.
89	            count = new Counter(animalClass.getName());
90	            counters.put(animalClass, count);
91	        }
92	        count.increment();
93	    }
94	
95	    /**
96	     * Indicate that an animal count has been completed.
97	     */
98	    public void countFinished()
99	    {
100	        countsValid = true;
101	    }
102	
103	    /**
104	     * Determine whether the simulation is still viable.
105	     * I.e., should it continue to run.
106	     * @return true If there is more than one species alive.
107	     */
108	    public boolean isViable(Field field)
109	    {
110	        // How many counts are non-zero.
111	        int nonZero = 0;
112	        if(!countsValid) {
113	            generateCounts(field);
114	        }
115	        for(Class key : counters.keySet()) {
116	            Counter info = counters.get(key);
117	            if(info.getCount() > 0) {
118	                nonZero++;
119	            }
120	        }
121	        return nonZero > 1;
122	    }
123	    
124	    /**
125	     * Generate counts of the number of foxes and rabbits.
126	     * These are not kept up to date as foxes and rabbits
127	     * are placed in the field, but only when a request
128	     * is made for the information.
129	     * @param field The field to generate the stats for.
130	     */
131	    private void generateCounts(Field field)
132	    {
133	        reset();
134	        field.forEachCell((row, col, animal) -> {
135	            if(animal != null) {
136	                incrementCount(animal.getClass());
137	            }
138	        });
139	        countsValid = true;
140	    }
141	}
