import java.util.Map;
import java.util.LinkedHashMap;

public class PvCheck {
    // Mirror of Simulator.countPopulation's lambda
    static Map<Class, Integer> count(Field field) {
        Map<Class, Integer> counts = new LinkedHashMap<>();
        field.forEachCell((row, col, occupant) -> {
            if (occupant != null) counts.merge(occupant.getClass(), 1, Integer::sum);
        });
        return counts;
    }

    public static void main(String[] a) {
        Field f = new Field(5, 6);
        int plants = 0, bears = 0, monkeys = 0;
        for (int r = 0; r < 5; r++)
            for (int c = 0; c < 6; c++) {
                int k = r * 6 + c;
                if (k % 4 == 0) { f.place(new Plant(false, f, new Location(r, c)), r, c); plants++; }
                else if (k % 5 == 0) { f.place(new Bear(false, f, new Location(r, c)), r, c); bears++; }
                else if (k % 7 == 0) { f.place(new Monkey(false, f, new Location(r, c)), r, c); monkeys++; }
            }
        Map<Class, Integer> counts = count(f);

        // independent manual recount
        int[] n = {0};
        f.forEachCell((r, c, o) -> { if (o != null) n[0]++; });
        int total = plants + bears + monkeys;

        PopulationSnapshot snap = new PopulationSnapshot(123, counts, "Sunny",
                (123 % 80 <= 55) ? "Day" : "Night", counts.size() > 1);
        String details = snap.getPopulationDetails();

        boolean countsOk = counts.getOrDefault(Plant.class, 0) == plants
                && counts.getOrDefault(Bear.class, 0) == bears
                && counts.getOrDefault(Monkey.class, 0) == monkeys
                && counts.values().stream().mapToInt(Integer::intValue).sum() == total
                && n[0] == total;
        boolean detailsOk = details.contains("Plant: " + plants)
                && details.contains("Bear: " + bears)
                && details.contains("Monkey: " + monkeys)
                && details.contains("Weather: Sunny")
                && details.contains("Time: Day");
        boolean viableOk = snap.isViable()
                && !new PopulationSnapshot(1, Map.of(Plant.class, 7), "Foggy", "Night", 1 > 1).isViable();
        // immutability: returned map must be unmodifiable
        boolean immutable;
        try { snap.getCounts().put(Sloth.class, 1); immutable = false; }
        catch (UnsupportedOperationException e) { immutable = true; }

        System.out.println("counts=" + counts);
        System.out.println("details=" + details);
        System.out.println("step preserved=" + (snap.getStep() == 123));
        System.out.println("countsOk=" + countsOk + " detailsOk=" + detailsOk
                + " viableOk=" + viableOk + " immutable=" + immutable);
        System.out.println(countsOk && detailsOk && viableOk && immutable && snap.getStep() == 123 ? "PASS" : "FAIL");
    }
}
